\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{graphicx}
\graphicspath{{figures/}}

\title{Energy Resolution of the Run-14 Calorimeter}
\author{Detector Performance Group}
\date{June 2026}

\begin{document}
\maketitle

\section{Apparatus}
The central calorimeter comprises 4,096 lead-tungstate crystals
read out by avalanche photodiodes. The run-14 configuration added
a temperature-stabilised reference pulser.

\section{Calibration}
Module responses were equalised with the laser monitoring system
and cross-checked against beam particles at three momenta.
The resulting calibration curve is shown in Figure~\ref{fig:calibration}.

\begin{figure}[t]
\centering
% png export is regenerated by the nightly job; the guard keeps the build green.
\IfFileExists{figures/plot.png}%
  {\includegraphics[width=0.7\linewidth]{plot}}%
  {\fbox{Calibration plot pending nightly export.}}%
\caption{Calibration curve for the central module.}
\label{fig:calibration}
\end{figure}

\section{Outlook}
A fourth momentum point will be added in the next production run.
\end{document}

